def normal_probability_below(x: float, mu: float = 0, sigma: float = 1) -&gt; float:
    return (1 + m.erf((x - mu) / m.sqrt(2) / sigma)) / 2

def normal_probability_above(lo: float, mu: float = 0, sigma: float = 1) -&gt; float:
