def a_b_test_statistic(N_A: int, A: int, N_B: int, B:int) -&gt; float:
    p_A, sigma_A = estimate_parameters(N_A, A)
    p_B, simga_B = estimate_parameters(N_B, B)

    return (p_B - p_A) / m.sqrt(sigma_A ** 2 + simga_B ** 2)

